// ES module slugify.mjs
export function slugify(input, options) {
  // Validate input
  if (typeof input !== 'string') {
    throw new TypeError('input must be a string');
  }

  // Default options
  const opts = {
    separator: '-',
    maxLength: Infinity,
    ...options
  };

  // Validate separator
  if (!['-', '_', '.'].includes(opts.separator)) {
    throw new RangeError('separator must be one of "-", "_", "."');
  }

  // Validate maxLength
  if (typeof opts.maxLength !== 'number' || opts.maxLength <= 0 || !Number.isInteger(opts.maxLength)) {
    throw new RangeError('maxLength must be a positive integer');
  }

  // Rule 1: Transliteration before normalization
  const translitMap = {
    'ß': 'ss', 'ẞ': 'ss',
    'æ': 'ae', 'Æ': 'ae',
    'ø': 'o', 'Ø': 'o',
    'œ': 'oe', 'Œ': 'oe',
    'đ': 'd', 'Đ': 'd',
    'ł': 'l', 'Ł': 'l',
    'þ': 'th', 'Þ': 'th',
    'ð': 'd', 'Ð': 'd'
  };

  let processed = input.replace(/[ßẞæÆøØœŒđĐłŁþÞðÐ]/g, char => translitMap[char]);

  // Rule 2: NFKD normalization and remove combining marks U+0300-U+036F
  processed = processed.normalize('NFKD');
  processed = processed.replace(/[\u0300-\u036f]/g, '');

  // Rule 3: Remove apostrophes (both straight and curly)
  processed = processed.replace(/['’]/g, '');

  // Rule 4: Lowercase
  processed = processed.toLowerCase();

  // Rule 5: Split into words – runs of [a-z0-9]
  // Everything else is a word boundary
  const words = processed.match(/[a-z0-9]+/g) || [];

  // Rule 6: Join with separator, no leading/trailing/repeated separators
  let slug = words.join(opts.separator);

  // Rule 7: Apply maxLength truncation
  if (slug.length > opts.maxLength) {
    // Find the longest prefix of whole words that fits
    const wordParts = words;
    let prefix = '';
    for (const word of wordParts) {
      const candidate = prefix ? prefix + opts.separator + word : word;
      if (candidate.length <= opts.maxLength) {
        prefix = candidate;
      } else {
        break;
      }
    }

    if (prefix) {
      slug = prefix;
    } else {
      // Even the first word is too long, truncate it
      slug = wordParts[0].slice(0, opts.maxLength);
    }
  }

  // Rule 8: Empty or whitespace/punctuation-only input returns ""
  // This is already handled by words being empty array
  // and slug being empty string after join

  // Rule 9: Idempotency is inherent because the pipeline is deterministic
  // and all transformations are idempotent on their own outputs

  return slug;
}
